"""Render ``CASES.md``: every case with its rule, status and the documentation it cites."""

from __future__ import annotations

from collections.abc import Sequence
from itertools import groupby
from urllib.parse import urlsplit

from lookml_conformance.cases import CATEGORIES, Case, Citation, Status

CATEGORY_TITLES = {
    "refinements": "Refinements",
    "includes": "Includes",
    "extends": "Extends",
    "model_scope": "Model scope",
    "explores": "Explores",
    "constants": "Constants",
    "syntax": "Syntax",
}
_HEADER = """\
# Cases

<!-- Generated by `lookml-conformance catalog` from cases/*/*/case.json. Do not edit by hand. -->

Each case states one rule, quotes the Looker documentation it comes from, and asserts how a
tool must resolve a minimal LookML project. *Confirmed* cases follow from the quoted documentation.
*Provisional* cases cover behavior the documentation leaves open; each names the open question and
the public source its expectation is pinned to.
"""
_INVALID_IN_LOOKER = (
    "Looker rejects this project. Tools may report an error but must not produce the forbidden result."
)


def render_catalog(cases: Sequence[Case], cases_path: str = "cases") -> str:
    lines = [_HEADER, *_summary(cases), ""]
    for category, members in groupby(cases, key=lambda case: case.category):
        lines += [f"## {CATEGORY_TITLES.get(category, category)}", ""]
        for case in members:
            lines += _case(case, cases_path)
    return "\n".join(lines).rstrip() + "\n"


def citation_label(citation: Citation) -> str:
    """A short label for a link: the page name plus its anchor, e.g. ``lookml-refinements#order``."""
    parts = urlsplit(citation.url)
    page = parts.path.rstrip("/").rsplit("/", 1)[-1] or parts.netloc
    return f"{page}#{parts.fragment}" if parts.fragment else page


def _summary(cases: Sequence[Case]) -> list[str]:
    lines = [
        "| Category | Cases | Confirmed | Provisional |",
        "| --- | ---: | ---: | ---: |",
    ]
    for category in CATEGORIES:
        members = [case for case in cases if case.category == category]
        if members:
            lines.append(_count_row(f"[{CATEGORY_TITLES[category]}](#{_slug(category)})", members))
    lines.append(_count_row("**Total**", cases))
    return lines


def _count_row(label: str, cases: Sequence[Case]) -> str:
    confirmed = sum(case.status is Status.CONFIRMED for case in cases)
    return f"| {label} | {len(cases)} | {confirmed} | {len(cases) - confirmed} |"


def _case(case: Case, cases_path: str) -> list[str]:
    directory = f"{cases_path}/{case.category}/{case.id}"
    lines = [
        f"### `{case.id}`",
        "",
        f"**{case.title}.** *{case.status.value}*",
        "",
        f"Rule: {case.rule}",
        "",
    ]
    lines += [
        f"> {citation.quote}<br>[{citation_label(citation)}]({citation.url})\n" for citation in case.citations
    ]
    if case.rationale:
        lines += [f"Why: {case.rationale}", ""]
    if case.provisional:
        lines += [
            f"Open question: {case.provisional.question}",
            "",
            f"Pinned to: {case.provisional.pinned_to}",
            "",
        ]
    if case.invalid_in_looker:
        lines += [_INVALID_IN_LOOKER, ""]
    lines += [f"Files: [`case.json`]({directory}/case.json) · [`project/`]({directory}/project)", ""]
    return lines


def _slug(category: str) -> str:
    return CATEGORY_TITLES[category].lower().replace(" ", "-")
